import requests, xml.etree.ElementTree as ET
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi'
r=requests.get(u,params={'db':'pubmed','id':'25093845','rettype':'abstract','retmode':'xml'},timeout=20)
print('HTTP',r.status_code)
root=ET.fromstring(r.text)
for el in root.findall('.//ArticleTitle'): print('TITLE:', ''.join(el.itertext()))
for el in root.findall('.//Abstract/AbstractText'): print('ABSTRACT:',el.get('Label',''), ''.join(el.itertext()))
for el in root.findall('.//Journal/Title'): print('JOURNAL:',el.text)
for el in root.findall('.//PubDate'): print('PUBDATE:', ' '.join(x.text or '' for x in el))
for el in root.findall('.//Author'): print('',end='')
print('PMID: 25093845')
